import { AgGridData } from 'components/Table/types';

import { ResourceAllocationChart, ResourceAllocationOverview } from '../types';
import { hasOverviewChartData } from './hasOverviewChartData';
import { hasOverviewRankingData } from './hasOverviewRankingData';
import { hasOverviewTableData } from './hasOverviewTableData';

export const hasOverviewData = (dataSource: {
  charts: { data: ResourceAllocationOverview };
  table: { data: AgGridData };
  ranking: { data: ResourceAllocationChart };
}): boolean =>
  hasOverviewChartData(dataSource.charts.data) ||
  hasOverviewTableData(dataSource.table.data) ||
  hasOverviewRankingData(dataSource.ranking.data);
